package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.nio.charset.Charset;
import java.nio.charset.CharsetEncoder;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.jsoup.Jsoup;
import org.jsoup.helper.Validate;
import org.jsoup.parser.Tag;
import org.jsoup.select.Elements;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class Document_title_TriageGen2Test {









    @Test
    public void testTitle_WithMultipleTitleTags() {
        // The implementation uses .first(), so it should return the first one found
        Document doc = Jsoup.parse("<html><head><title>First</title><title>Second</title></head><body></body></html>");
        String result = doc.title();
        assertEquals("First", result);
    }


}

package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.nio.charset.Charset;
import java.nio.charset.CharsetEncoder;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.jsoup.Jsoup;
import org.jsoup.helper.Validate;
import org.jsoup.parser.Tag;
import org.jsoup.select.Elements;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class Document_title_TriageGen2Test {











    @Test
    public void testTitle_WithTitleInBody() {
        // Even if in body, getElementsByTag("title") should find it
        Document doc = Jsoup.parse("<html><head></head><body><title>Body Title</title></body></html>");
        String result = doc.title();
        assertEquals("Body Title", result);
    }
}
